def test_extract_copy_statements_returns_all_five_in_source_order():
    statements = extract_copy_statements(CBACT04C_SOURCE)
    assert [s.copybook_name for s in statements] == [
        "CVTRA01Y",
        "CVACT03Y",
        "CVTRA02Y",
        "CVACT01Y",
        "CVTRA05Y",
    ]


def test_extract_copy_statements_raw_text_is_the_straight_copy_statement():
    statements = extract_copy_statements(CBACT04C_SOURCE)
    cvact01y = next(s for s in statements if s.copybook_name == "CVACT01Y")
    assert cvact01y.raw_text == "COPY CVACT01Y."


def test_copy_replacing_is_rejected_not_silently_treated_as_straight_copy():
    source = "COPY CVTRA01Y REPLACING ==:TAG:== BY ==WS==."
    with pytest.raises(UnsupportedCopyConstructError) as exc_info:
        extract_copy_statements(source)
    assert exc_info.value.copybook_name == "CVTRA01Y"


def test_copy_replacing_among_straight_copies_still_raises():
    # A REPLACING clause anywhere in the source must block extraction, not just be skipped
    # while the straight COPY statements around it are returned.
    source = "COPY CVTRA01Y.\nCOPY CVACT01Y REPLACING ==A== BY ==B==.\nCOPY CVTRA05Y."
    with pytest.raises(UnsupportedCopyConstructError):
        extract_copy_statements(source)


